    [Fact]
    public async Task A_dahua_dav_recording_converts_to_mp4()
    {
        // FFmpeg has no DHAV muxer, so the recording is put together here the way Dahua cameras write it: H.264 frames
        // and G.711 A-law sound in DHAV chunks.
        SkipUnlessInstalled();
        var folder = fx.NewFolder();
        var h264 = await MakeClipAsync(folder, "camera.h264", size: "160x120", audio: false,
            extra: ["-c:v", "libx264", "-g", "25", "-bsf:v", "h264_metadata=aud=insert"]);
        var alaw = Path.Combine(folder, "camera.alaw");
        await RunAsync(Tools!.Value.Ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi",
            "-i", "sine=frequency=440:sample_rate=8000:duration=2", "-ac", "1", "-f", "alaw", alaw]);
        var dav = Path.Combine(folder, "ch01_main.dav");
        await File.WriteAllBytesAsync(dav, Dhav.Recording(await File.ReadAllBytesAsync(h264, TestContext.Current.CancellationToken),
            await File.ReadAllBytesAsync(alaw, TestContext.Current.CancellationToken), 160, 120), TestContext.Current.CancellationToken);

        var probe = await ProcessRunner.RunAsync(Tools!.Value.Ffprobe, ["-v", "error", "-show_entries", "format=format_name", "-of", "csv=p=0", dav],
            TimeSpan.FromMinutes(1), CancellationToken.None);
        Assert.Equal("dhav", probe.StandardOutput.Trim());

        var probed = await ProbeAsync(await ConvertAsync(dav, "mp4"));
        var video = probed.Video;
        Assert.NotNull(video);
        Assert.Equal(("h264", 160, 120, 50), (video.Codec, video.Width, video.Height, video.Frames));
        Assert.Equal("aac", probed.Audio?.Codec);
        Assert.InRange(probed.Duration, 1.7, 2.4);
    }

    /// <summary>Dahua's DHAV container, as far as FFmpeg's dhav demuxer reads it.</summary>
    private static class Dhav
    {
        /// <summary>
        /// One video chunk per H.264 access unit (each starting with an access unit delimiter) at 25 fps, each followed
        /// by 40 ms of 8 kHz mono A-law sound.
        /// </summary>
        public static byte[] Recording(byte[] annexB, byte[] alaw, int width, int height)
        {
            var units = AccessUnits(annexB);
            var output = new MemoryStream();
            for (var i = 0; i < units.Count; i++)
            {
                var ms = i * 40;
                // 0x80: size in units of 8 pixels; 0x81: codec 8 (H.264) at 25 fps.
                byte[] video = [0x80, 0, (byte)(width / 8), (byte)(height / 8), 0x81, 0, 0x08, 25];
                Chunk(output, IsKeyFrame(units[i]) ? (byte)0xFD : (byte)0xFC, i + 1, ms, video, units[i]);
                var sound = alaw.AsSpan().Slice(Math.Min(i * 320, alaw.Length), Math.Clamp(alaw.Length - i * 320, 0, 320));
                // 0x83: one channel, codec 0x0E (A-law), sample rate 0 (8 kHz).
                if (!sound.IsEmpty)
                    Chunk(output, 0xF0, i + 1, ms, [0x83, 1, 0x0E, 0], sound);
            }
            return output.ToArray();
        }

        private static void Chunk(MemoryStream output, byte type, int number, int ms, ReadOnlySpan<byte> extension, ReadOnlySpan<byte> payload)
        {
            var length = 24 + extension.Length + payload.Length + 8;
            var seconds = ms / 1000;
            // Wall-clock time of the chunk: 2026-10-05 15:mm:ss.
            var date = (uint)(seconds % 60 | seconds / 60 % 60 << 6 | 15 << 12 | 5 << 17 | 10 << 22 | (2026 - 2000) << 26);
            Span<byte> header = stackalloc byte[24];
            "DHAV"u8.CopyTo(header);
            header[4] = type;
            BinaryPrimitives.WriteInt32LittleEndian(header[8..], number);
            BinaryPrimitives.WriteInt32LittleEndian(header[12..], length);
            BinaryPrimitives.WriteUInt32LittleEndian(header[16..], date);
            BinaryPrimitives.WriteUInt16LittleEndian(header[20..], (ushort)ms);
            header[22] = (byte)extension.Length;
            output.Write(header);
            output.Write(extension);
            output.Write(payload);
            output.Write("dhav"u8);
            Span<byte> trailer = stackalloc byte[4];
            BinaryPrimitives.WriteInt32LittleEndian(trailer, length);
            output.Write(trailer);
        }

        private static List<byte[]> AccessUnits(byte[] annexB)
        {
            byte[] delimiter = [0, 0, 0, 1, 9];
            var starts = new List<int>();
            for (var at = annexB.AsSpan().IndexOf(delimiter); at >= 0;)
            {
                starts.Add(at);
                var next = annexB.AsSpan(at + 1).IndexOf(delimiter);
                at = next < 0 ? -1 : at + 1 + next;
            }
            return starts.Select((start, i) => annexB[start..(i + 1 < starts.Count ? starts[i + 1] : annexB.Length)]).ToList();
        }

        /// <summary>An access unit with an IDR slice (NAL type 5).</summary>
        private static bool IsKeyFrame(byte[] unit)
        {
            for (var i = 0; i + 3 < unit.Length; i++)
            {
                if (unit[i] == 0 && unit[i + 1] == 0 && unit[i + 2] == 1 && (unit[i + 3] & 0x1F) == 5)
                    return true;
            }
            return false;
        }
    }

    [Theory]
    [InlineData("ch01_20261005150000.mp4", true, false)]
    [InlineData("ch01_20261005150000.mp4", true, true)]
    [InlineData("hiv00000.mp4", false, false)]
    [InlineData("hiv00000.mp4", false, true)]
    [InlineData("ch01.264", true, true)]
    public async Task A_hikvision_recording_converts_to_mp4_with_its_sound(string name, bool imkhHeader, bool muLaw)
    {
        // iVMS-4200 / NVR exports (IMKH header) and SD-card recordings (no header) are MPEG program streams with
        // G.711 sound. Without the header, FFmpeg reads mu-law sound as MP2 and fails, unless Filee adds the header.
        SkipUnlessInstalled();
        var folder = fx.NewFolder();
        var h264 = await MakeClipAsync(folder, "camera.h264", size: "160x120", audio: false,
            extra: ["-c:v", "libx264", "-g", "25", "-bsf:v", "h264_metadata=aud=insert"]);
        var g711 = Path.Combine(folder, "camera.g711");
        await RunAsync(Tools!.Value.Ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y", "-f", "lavfi",
            "-i", "sine=frequency=440:sample_rate=8000:duration=2", "-ac", "1", "-f", muLaw ? "mulaw" : "alaw", g711]);
        var recording = Path.Combine(folder, name);
        await File.WriteAllBytesAsync(recording, HikvisionRecording.Write(
            await File.ReadAllBytesAsync(h264, TestContext.Current.CancellationToken),
            await File.ReadAllBytesAsync(g711, TestContext.Current.CancellationToken), muLaw, imkhHeader),
            TestContext.Current.CancellationToken);

        var probed = await ProbeAsync(await ConvertAsync(recording, "mp4"));
        var video = probed.Video;
        Assert.NotNull(video);
        Assert.Equal(("h264", 160, 120, 50), (video.Codec, video.Width, video.Height, video.Frames));
        Assert.Equal("aac", probed.Audio?.Codec);
        Assert.InRange(probed.Duration, 1.7, 2.4);
    }

