        var probed = await ProbeAsync(output);
        Assert.Equal((240, 180), (probed.Video!.Width, probed.Video.Height));
        Assert.Equal("aac", probed.Audio?.Codec);
        Assert.InRange(probed.Duration, 1.7, 2.4);
