    [Theory]
    [InlineData("mp4", "mov_text")]
    [InlineData("mov", "mov_text")]
    [InlineData("webm", "webvtt")]
    public async Task An_mkv_with_srt_subtitles_keeps_them_as_a_switchable_track(string target, string codec)
    {
        SkipUnlessInstalled();
        // #789: an MKV with a Korean SRT track, made here.
        var folder = fx.NewFolder();
        var srt = Path.Combine(folder, "episode.srt");
        await File.WriteAllTextAsync(srt, "1\r\n00:00:00,500 --> 00:00:01,500\r\n안녕하세요\r\n\r\n", TestContext.Current.CancellationToken);
        var source = Path.Combine(folder, "episode.mkv");
        await RunAsync(Tools!.Value.Ffmpeg, ["-hide_banner", "-nostdin", "-v", "error", "-y",
            "-f", "lavfi", "-i", "testsrc2=size=160x120:rate=25:duration=2",
            "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=48000:duration=2", "-i", srt,
            "-map", "0", "-map", "1", "-map", "2", "-c:v", "libx264", "-c:a", "aac", "-c:s", "srt", "-metadata:s:s:0", "language=kor", source]);

        var output = await ConvertAsync(source, target);

        var info = await MediaInfo.ProbeAsync(Tools!.Value.Ffprobe, output, CancellationToken.None);
        var track = Assert.Single(info.Subtitles);
        Assert.Equal((codec, "kor"), (track.Codec, track.Language));
        // The cue still starts half a second in. Timed text fills the gap before it with an empty 2-byte sample.
        var packets = await ProcessRunner.RunAsync(Tools!.Value.Ffprobe,
            ["-v", "error", "-select_streams", "s:0", "-show_entries", "packet=pts_time,size", "-of", "csv=p=0", output],
            TimeSpan.FromMinutes(1), CancellationToken.None);
        var cue = packets.StandardOutput.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(line => line.Split(','))
            .First(p => int.Parse(p[1], CultureInfo.InvariantCulture) > 2);
        Assert.InRange(double.Parse(cue[0], CultureInfo.InvariantCulture), 0.45, 0.55);
    }

    [Fact]
    public async Task Every_target_format_is_written_with_the_planned_codecs()
    {
        SkipUnlessInstalled();
        var folder = fx.NewFolder();
        var source = await MakeClipAsync(folder, "all.mp4", seconds: 1, size: "160x120");
        var failures = new System.Collections.Concurrent.ConcurrentBag<string>();
        var targets = MediaEncoding.VideoTargets.Concat(MediaEncoding.AudioTargets).ToList();
        await Parallel.ForEachAsync(targets, new ParallelOptions { MaxDegreeOfParallelism = 3 }, async (entry, _) =>
        {
            var (target, spec) = entry;
            try
            {
                var probed = await ProbeAsync(await ConvertAsync(source, target));
                if (spec.VideoCodec is not null && probed.Video?.Codec != Decoded(spec.VideoCodec))
                    failures.Add($"{target}: video {probed.Video?.Codec}");
                if (spec.VideoCodec is null && probed.Video is not null)
                    failures.Add($"{target}: unexpected video stream");
                if (probed.Audio?.Codec != Decoded(spec.AudioCodec))
                    failures.Add($"{target}: audio {probed.Audio?.Codec}");
                if (probed.Duration is < 0.7 or > 1.5)
                    failures.Add($"{target}: duration {probed.Duration}");
                if (target is "vob" or "dv" && probed.Video is { } frame && (frame.Width, frame.Height) != (720, 576)) // 25 fps source = PAL
                    failures.Add($"{target}: frame {frame.Width}×{frame.Height}");
            }
            catch (Exception ex)
            {
                failures.Add($"{target}: {ex.Message}");
            }
        });
        Assert.Empty(failures);
    }

    [Fact]
    public async Task Hevc_and_av1_presets_write_those_codecs_and_keep_ten_bits()
    {
        SkipUnlessInstalled();
        var folder = fx.NewFolder();
        var h264 = await MakeClipAsync(folder, "clip.mp4", seconds: 1, size: "320x240");
        // A 10-bit HLG source, like a phone's HDR video.
        var hdr = await MakeClipAsync(folder, "hdr.mkv", seconds: 1, size: "320x240",
            extra: ["-c:v", "libx265", "-pix_fmt", "yuv420p10le",
                    "-x265-params", "colorprim=bt2020:transfer=arib-std-b67:colormatrix=bt2020nc:log-level=error"]);

        async Task<JsonElement> VideoOf(string file)
        {
            var result = await ProcessRunner.RunAsync(Tools!.Value.Ffprobe,
                ["-v", "error", "-select_streams", "v:0", "-show_entries", "stream=codec_name,codec_tag_string,pix_fmt,color_transfer", "-of", "json", file],
                TimeSpan.FromMinutes(1), CancellationToken.None);
            return JsonDocument.Parse(result.StandardOutput).RootElement.GetProperty("streams")[0].Clone();
        }

        var hevc = await VideoOf(await ConvertAsync(h264, "mp4", new MediaOptions { VideoCodec = VideoCodec.Hevc }));
        Assert.Equal(("hevc", "hvc1", "yuv420p"), (hevc.GetProperty("codec_name").GetString(), hevc.GetProperty("codec_tag_string").GetString(), hevc.GetProperty("pix_fmt").GetString()));

        var av1 = await VideoOf(await ConvertAsync(hdr, "mp4", new MediaOptions { VideoCodec = VideoCodec.Av1 }));
        Assert.Equal(("av1", "yuv420p10le", "arib-std-b67"), (av1.GetProperty("codec_name").GetString(), av1.GetProperty("pix_fmt").GetString(), av1.GetProperty("color_transfer").GetString()));

        var webm = await VideoOf(await ConvertAsync(h264, "webm", new MediaOptions { VideoCodec = VideoCodec.Av1, Quality = MediaQuality.Small }));
        Assert.Equal("av1", webm.GetProperty("codec_name").GetString());
    }

